parameters.text:
==Analizza questi prodotti da ordinare al fornitore {{ $json.SupplierName }}:

{{ $json.ProductSummary }}

Note fornitore: {{ $json.SupplierNotes }}
Email fornitore: {{ $json.SupplierEmail }}

AZIONE: Crea UNA SOLA bozza email che includa TUTTI i prodotti elencati sopra in un unico ordine. Una volta creata la bozza, rispondi solo con 'Bozza creata' e fermati.

parameters.jsCode:
const items = $input.all();

const grouped = {};

items.forEach(function(item) {
  const email = item.json.SupplierEmail || 'nessun_fornitore';

  if (!grouped[email]) {
    grouped[email] = {
      SupplierEmail: email,
      SupplierName: item.json.SupplierName,
      SupplierNotes: item.json.SupplierNotes,
      products: []
    };
  }

  grouped[email].products.push({
    ProductName: item.json.ProductName,
    SupplierCode: item.json.SupplierCode,
    SuggestedOrderQty: item.json.SuggestedOrderQty,
    Unit: item.json.UNIT || 'unità',
    CurrentStock: item.json.CurrentStock,
    MIN_STOCK: item.json.MIN_STOCK,
    EXPIRY_DATE: item.json.EXPIRY_DATE,
    CatalogPrice: item.json.CatalogPrice
  });
});

return Object.values(grouped).map(function(supplier) {
  const productLines = supplier.products.map(function(p) {
    return '- ' + p.ProductName + ' | Codice: ' + p.SupplierCode + ' | Quantità: ' + p.SuggestedOrderQty + ' ' + p.Unit + ' | Giacenza attuale: ' + p.CurrentStock + ' ' + p.Unit;
  }).join('\n');

  return {
    json: {
      SupplierEmail: supplier.SupplierEmail,
      SupplierName: supplier.SupplierName,
      SupplierNotes: supplier.SupplierNotes,
      ProductSummary: productLines,
      products: supplier.products
    }
  };
});

const draft = $input.first().json;
const orderData = $('GROUP BY SUPPLIER').first().json;

const threadId = draft.threadId || '';
const products = orderData.products || [];

return products.map(function(p) {
  return {
    json: {
      threadId: threadId,
      supplierEmail: orderData.SupplierEmail,
      supplierName: orderData.SupplierName,
      productName: p.ProductName,
      supplierCode: p.SupplierCode,
      orderedQty: p.SuggestedOrderQty,
      orderedUnit: p.Unit,
      catalogPrice: p.CatalogPrice
    }
  };
});

const items = $input.all().filter(i => i.json.batch_id);

if (items.length === 0) {
  return [];
}

const lines = items.map(function(it) {
  const d = it.json;
  const days = d.DaysToExpiry;
  const stato = days < 0 
    ? 'GIÀ SCADUTO da ' + Math.abs(days) + ' giorni'
    : days === 0 
      ? 'SCADE OGGI' 
      : 'scade tra ' + days + ' giorni';
  return '- ' + d.ProductName + ' (lotto ' + (d.batch_number || 'n/d') + '): ' 
    + d.BatchQuantity + ' ' + (d.UNIT || '') + ' — ' + stato 
    + ' (' + d.expiry_date + ')';
}).join('\n');

const body = 'Lotti in scadenza nei prossimi 3 giorni:\n\n' + lines 
  + '\n\nUsare con priorità i lotti più vicini alla scadenza (FEFO).';

return [{ json: { alertBody: body, count: items.length } }];

